it('renders only a window of a large list', () => {
  const items = Array.from({ length: 10_000 }, (_, i) => `row ${i}`);
  render(<VirtualList items={items} height={360} renderRow={(s) => <span>{s}</span>} />);
  expect(screen.getByText('row 0')).toBeInTheDocument();
  expect(screen.queryByText('row 5000')).not.toBeInTheDocument();
  expect(screen.getAllByText(/^row /).length).toBeLessThan(30);
