## Problem statement

Create a signup form with email and password. Invalid submissions must be perceivable and operable with keyboard and screen readers.

## Expected solution

```tsx
import { useEffect, useId, useRef, useState, type FormEvent } from 'react';

interface Values { email: string; password: string }
type Errors = Partial<Record<keyof Values, string>>;

export function validate(v: Values): Errors {
  const errors: Errors = {};
  if (!/^\S+@\S+\.\S+$/.test(v.email)) errors.email = 'Enter an email address in the format name@example.com';
  if (v.password.length < 12) errors.password = 'Password must be at least 12 characters';
  return errors;
}

export function SignupForm({ onSubmit }: { onSubmit: (v: Values) => Promise<void> }) {
  const id = useId();
  const [values, setValues] = useState<Values>({ email: '', password: '' });
  const [errors, setErrors] = useState<Errors>({});
  const [submitting, setSubmitting] = useState(false);
  const summaryRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (Object.keys(errors).length > 0) summaryRef.current?.focus();
  }, [errors]);

  async function handleSubmit(e: FormEvent) {
    e.preventDefault();
    const found = validate(values);
    setErrors(found);
    if (Object.keys(found).length > 0) return;
    setSubmitting(true);
    try { await onSubmit(values); } finally { setSubmitting(false); }
  }

  const field = (name: keyof Values, label: string, type: string) => (
    <div>
      <label htmlFor={`${id}-${name}`}>{label}</label>
      <input
        id={`${id}-${name}`}
        type={type}
        value={values[name]}
        onChange={(e) => setValues({ ...values, [name]: e.target.value })}
        aria-invalid={errors[name] ? true : undefined}
        aria-describedby={errors[name] ? `${id}-${name}-error` : undefined}
        autoComplete={name === 'email' ? 'email' : 'new-password'}
      />
      {errors[name] && <p id={`${id}-${name}-error`}>{errors[name]}</p>}
    </div>
  );

  const hasErrors = Object.keys(errors).length > 0;
  return (
    <form onSubmit={handleSubmit} noValidate>
      {hasErrors && (
        <div ref={summaryRef} tabIndex={-1} role="group" aria-labelledby={`${id}-summary`}>
          <h2 id={`${id}-summary`}>There is a problem</h2>
          <ul>{Object.entries(errors).map(([k, m]) => <li key={k}>{m}</li>)}</ul>
        </div>
      )}
      {field('email', 'Email', 'email')}
      {field('password', 'Password', 'password')}
      <button type="submit" disabled={submitting}>{submitting ? 'Creating account…' : 'Create account'}</button>
    </form>
  );
}
```

## Explanation

Native labels give each control an accessible name and a larger click target. `useId` produces unique, SSR-safe ids. `aria-invalid` plus `aria-describedby` makes screen readers announce the error when the field is focused. The error summary is focusable (`tabIndex=-1`) and focused programmatically so keyboard and assistive technology users land on the explanation, a pattern recommended by several government design systems. Colour is never the only indicator of an error, and `autocomplete` values help password managers and users with cognitive or motor impairments.

## Time and space complexity

Not applicable.

## Edge cases

- Both fields empty: the summary lists both messages.
- Fixing one error and resubmitting updates the summary and refocuses it.
- Submit while submitting: the button is disabled; guard in the handler for Enter key repeats if needed.
- Zoom to 200 percent and high-contrast modes: avoid fixed heights and rely on text, not colour.

