import { expect, it, vi } from 'vitest';
import { TtlCache } from './ttlCache';

it('coalesces concurrent misses and honours TTL', async () => {
  let t = 0;
  const loader = vi.fn(async () => 'v');
  const cache = new TtlCache<string>(1000, 0, () => t);
  await Promise.all(Array.from({ length: 10 }, () => cache.get('k', loader)));
  expect(loader).toHaveBeenCalledTimes(1);
  await cache.get('k', loader);
  expect(loader).toHaveBeenCalledTimes(1);
  t = 1001;
  await cache.get('k', loader);
  expect(loader).toHaveBeenCalledTimes(2);
});
```

## Production concerns

- In-process caches are per instance; use Redis for shared state and `SET key value NX PX` for a lock, or accept per-instance loading.
- Consider stale-while-revalidate: serve expired data while refreshing in the background.
- Emit hit, miss and load-time metrics.
- Never cache user-specific data under a shared key.

## Likely interviewer extensions

- Add stale-while-revalidate.
- Implement the distributed version with Redis.
- Add a maximum size with LRU eviction.

## Problem statement

`POST /orders` may be retried by clients or gateways after timeouts. Ensure that retries never create duplicate orders.

## Expected solution

```ts
import { createHash } from 'node:crypto';

export interface OrderInput { customerId: string; items: { sku: string; qty: number }[] }
export interface OrderResponse { orderId: string; total: number }

export type Stored = { requestHash: string; status: 'in_progress' | 'completed'; response?: OrderResponse };

export interface IdempotencyStore {
  /** Atomically insert; backed by a UNIQUE constraint on key. */
  begin(key: string, requestHash: string): Promise<{ started: true } | { started: false; existing: Stored }>;
  complete(key: string, response: OrderResponse): Promise<void>;
  release(key: string): Promise<void>;
}

export class IdempotencyError extends Error {
  constructor(public readonly status: 409 | 422, message: string) {
    super(message);
  }
}

export async function createOrderIdempotent(
  store: IdempotencyStore,
  create: (input: OrderInput) => Promise<OrderResponse>,
  key: string,
  input: OrderInput,
): Promise<OrderResponse> {
  const requestHash = createHash('sha256').update(JSON.stringify(input)).digest('hex');
  const begun = await store.begin(key, requestHash);

  if (!begun.started) {
    const { existing } = begun;
    if (existing.requestHash !== requestHash) throw new IdempotencyError(422, 'Key reused with a different payload');
    if (existing.status === 'completed' && existing.response) return existing.response;
    throw new IdempotencyError(409, 'A request with this key is in progress');
  }

  try {
    const response = await create(input);
    await store.complete(key, response);
    return response;
  } catch (err) {
    await store.release(key);
    throw err;
  }
}

// Postgres: INSERT INTO idempotency_keys (key, request_hash, status) VALUES ($1,$2,'in_progress')
//           ON CONFLICT (key) DO NOTHING RETURNING key;   -- zero rows means "exists", then SELECT it.
// MongoDB: unique index on key; treat duplicate key error code 11000 as "exists".
```

{{diagram:idem-flow}}

## Explanation

The unique constraint is the concurrency control: two simultaneous requests both try to insert and exactly one succeeds, so there is no check-then-insert race. Hashing the payload detects clients that reuse a key for different requests, a bug that would otherwise silently return the wrong order. Persisting the response lets a retry get the same answer, including after a crash. Ideally the order insert and `complete` share one database transaction; if they cannot, `in_progress` rows need a lease expiry so a crashed worker does not block the key forever.

## Time and space complexity

O(1) database operations per request plus one hash over the payload.

## Edge cases

- Crash after creating the order but before `complete`: use a transaction or reconcile by a natural unique key such as client order reference.
- `JSON.stringify` depends on key order; canonicalise before hashing if clients differ.
- Keys must expire (for example after 24 hours) with a cleanup job.
- Scope keys per customer or tenant so one client cannot collide with another.

## Unit tests

```ts
import { expect, it } from 'vitest';
import { createOrderIdempotent, IdempotencyError, type IdempotencyStore, type Stored } from './idempotency';

const memoryStore = (): IdempotencyStore => {
  const rows = new Map<string, Stored>();
  return {
    async begin(key, requestHash) {
      const existing = rows.get(key);
      if (existing) return { started: false, existing };
      rows.set(key, { requestHash, status: 'in_progress' });
      return { started: true };
    },
    async complete(key, response) { rows.set(key, { ...rows.get(key)!, status: 'completed', response }); },
    async release(key) { rows.delete(key); },
  };
};

it('creates once and replays', async () => {
  const store = memoryStore();
  let calls = 0;
  const create = async () => ({ orderId: `o${++calls}`, total: 10 });
  const input = { customerId: 'c', items: [{ sku: 's', qty: 1 }] };
  const a = await createOrderIdempotent(store, create, 'k1', input);
  const b = await createOrderIdempotent(store, create, 'k1', input);
  expect(b).toEqual(a);
  expect(calls).toBe(1);
  await expect(createOrderIdempotent(store, create, 'k1', { ...input, customerId: 'x' })).rejects.toBeInstanceOf(IdempotencyError);
